const CCL_GAP = paint(RAW_A, 'CCL gap', 'var(--k-crimson)', 'k-crimson');
const BASE = paint(RAW_B, 'Real base', 'var(--k-crimson)', 'k-crimson');
const M2 = paint(RAW_B, 'Real M2', 'var(--k-blue)', 'k-blue');

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function monthLabel(d) {
  return `${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}
function fmtPct(v) {
  return `${v.toFixed(1)} %`;
}
function fmtIndex(v) {
  return v.toFixed(1);
}

function extent(seriesList) {
  let lo = Infinity;
  let hi = -Infinity;
  for (const s of seriesList) {
    for (const v of s.y) {
      if (Number.isFinite(v)) {
        if (v < lo) lo = v;
        if (v > hi) hi = v;
      }
    }
  }
  return [lo, hi];
}
const [LO_A, HI_A] = extent([BLUE_GAP, CCL_GAP]);
const [LO_B, HI_B] = extent([BASE, M2]);

// S2-2-fix-c: Q11 ruling, panel A only ("symlog with named ticks"). The
// constant is d3-scale's own symlog "linear region width" parameter — a
// smaller constant spreads small values apart MORE; brief's own suggested
// starting point (1) measured (`node -e` against this kit's own d3-scale,
// report has the transcript) at a representative 700px plot height:
// separates the beat-2 close numbers, Blue gap 0.69 % and CCL gap-adjacent
// Phase mean 1.4 %/5.5 %, by ~175px (0.69->5.5 alone) — more than 10x the
// 16px terminus cap this pack's own checker enforces, so no further tuning
// bought anything; kept at the brief's own default.
const SYMLOG_CONSTANT_A = 1;
const Y_A_TICKS = [0, 1, 3, 10, 30, 100];
// S2-2-fix-c round 2: no space before `%` — same reasoning as
// `01-three-regimes.js`'s own identical round-2 fix (every reserved px
// here also comes out of the shared x-axis's own tick-label budget).
function fmtYTickPct(v) {
  return `${v}%`;
}

// S2-2-fix-b P1-2, lever 1: the last DEFINED value of a series — what its
// end label will actually show at t=1 (same helper as
// 01-three-regimes.js's own, duplicated rather than shared — scene-local,
// not a kit primitive).
function lastDefinedValue(series) {
  for (let i = series.y.length - 1; i >= 0; i--) {
    if (Number.isFinite(series.y[i])) return series.y[i];
  }
  return null;
}

// §3.1: scales recompute inside `draw` from `stage.safe` every call.
//
// S2-2-fix-b P1-2, lever 1: same gutter fix as 01-three-regimes.js's own
// `buildScales` — panel A's and panel B's x-ranges both end on the safe
// area's true right edge today, so every named end label (Blue gap/CCL
// gap/Phase mean in A; Real base/Real M2 in B) draws the exact "leftward,
// back over the line" flip the brief describes. Shrunk by the widest end
// label THIS panel will actually draw at the current viewport, measured
// (never guessed) via `measureEndLabelGutter`. Panel A's own event flags
// and panel B's `hundred` reference line both read off this same scale, so
// they move with it — correct, per the brief.
// S2-2-fix-c: same measured-gutter discipline as `measureEndLabelGutter`
// (never guessed) — the widest of panel A's own 6 named y-ticks ("100 %"),
// probed inside a throwaway `<g class="axis">` so `getComputedTextLength`
// reads the real `.axis text` CSS rule, not the SVG default. `+6`/`+9`
// (tick mark / d3-axis's own default tickPadding) mirror
// `measureEndLabelGutter`'s own `+6` buffer reasoning. Panel-A-local (not
// shared with `01-three-regimes.js`'s own copy — scene-local per this
// file's own `boxesIntersect`/`lastDefinedValue` convention, header note).
function measureYAxisGutterA(stage) {
  const wrap = stage.append('g').attr('class', 'axis').attr('opacity', 0);
  const probe = wrap.append('text').attr('x', -9999).attr('y', -9999);
  const node = probe.node();
  let max = 0;
  if (node && typeof node.getComputedTextLength === 'function') {
    Y_A_TICKS.forEach((d) => {
      probe.text(fmtYTickPct(d));
      const w = node.getComputedTextLength();
      if (w > max) max = w;
    });
  }
  wrap.remove();
  // S2-2-fix-c round 2: `+9` is d3-axis's real default `tickSizeInner(6) +
  // tickPadding(3)` — see `01-three-regimes.js`'s own identical fix for the
  // source citation (was `+6+9`, double-counting the tick mark).
  return Math.max(max + 9, 24);
}

function buildScalesA(stage, ctx) {
  const showName = typeof matchMedia !== 'function' || matchMedia(`(min-width: ${NAME_LABEL_MIN_WIDTH_PX}px)`).matches;
  const gutter = measureEndLabelGutter(stage, [
    { label: BLUE_GAP.label, value: lastDefinedValue(BLUE_GAP), fmt: fmtPct, showName },
    { label: CCL_GAP.label, value: lastDefinedValue(CCL_GAP), fmt: fmtPct, showName },
    { label: 'Phase mean', value: PHASE_MEAN_PCT[PHASE_MEAN_PCT.length - 1], fmt: fmtPct, showName }
  ]);
  const yAxisGutter = measureYAxisGutterA(stage);
  const x = ctx.d3.scale
    .scaleTime()
    .domain(ctx.d3.array.extent(BLUE_GAP.x.values))
    .range([stage.safe.x + yAxisGutter, stage.safe.x + stage.safe.width - gutter]);
  // Q11 ruling, verbatim starting point (this file's own header note above
  // has the measurement): symlog, not linear — the premium runs two orders
  // of magnitude (100.9 -> 1.4 %) and every current-day value used to
  // compress into the domain's own bottom ~1 %.
  //
  // S2-2-fix-c round 2, `.clamp(true)`: the domain is `[0, HI_A]` (brief,
  // verbatim) — BLUE_GAP's own daily series dips slightly negative a
  // handful of times (min -3.67, real data, `extent()`'s own `LO_A`, never
  // read by this scale). Symlog is UNBOUNDED and MOST sensitive exactly
  // near zero (that sensitivity is the entire reason for choosing it —
  // this file's own header note), so an unclamped negative input
  // extrapolates well past the axis line rather than a proportionally
  // small dip the way it would under linear — measured: even a small daily
  // swing (-0.72, real data, April 2026) rendered ~73px below `y(0)` at
  // constant=1, striking the x-axis's own tick-label row (`path-text`,
  // "Blue gap"/"CCL gap" vs "May 2026", every width). Raising the constant
  // enough to tame that (C=10 still leaves a 16px overshoot, measured)
  // costs most of the 0.7 %/5.5 % separation this scale exists for.
  // Clamping is the correct tool instead: it only touches inputs OUTSIDE
  // the declared domain, pinning them to `y(0)` exactly rather than
  // amplifying them into a false excursion — no visible value inside
  // `[0, HI_A]` (which is everything the caption/labels ever cite) moves
  // at all.
  const y = ctx.d3.scale.scaleSymlog().domain([0, HI_A]).constant(SYMLOG_CONSTANT_A).clamp(true).range([stage.safe.y + stage.safe.height, stage.safe.y]);
  return { x, y };
}

// S2-2-fix-c: the new panel-A y-axis. `axisMorph(axisG, y, y, 1, …)` is an
// identity morph (rendering/formatting only, same reasoning as
// `01-three-regimes.js`'s own `drawYAxis`) — panel A's `y` scale doesn't
// tween between two DIFFERENT scales the way the shared x-axis does
// (`drawAxis` below); it's one symlog scale, recomputed fresh every frame
// from `stage.safe` like every other scale in this file (§3.1). `orient:
// axisLeft` is why `axisMorph.js` needed the one-line horizontal-only gate
// (see that file's own header note).
function drawYAxisA(gA, y, xPos) {
  gA.select('g.axis.y-axis').remove();
  const axisG = gA.append('g').attr('class', 'axis y-axis').attr('transform', `translate(${xPos},0)`);
  axisMorph(axisG, y, y, 1, { ticks: Y_A_TICKS, orient: axisLeft, format: fmtYTickPct });
}

// S2-2 ruling's "the axis label carrying 'log scale'" — `.annot`, the same
// register panel B's own "100 (Dec 2023)" reference-line caption already
// uses (`gB`'s own `text.hundred-annot` below), not an axis title (§1.5
// bans those). Placed bottom-left, inside the plot: panel A's own two
// series both open near 100 % (Jan 2022), so that corner (low value, early
// date) is the one place nothing else ever draws.
function drawLogScaleAnnot(gA, xPos, safe) {
  gA.selectAll('text.log-scale-annot')
    .data([null])
    .join('text')
    .attr('class', 'annot log-scale-annot')
    .attr('x', xPos + 4)
    .attr('y', safe.y + safe.height - 6)
    .attr('text-anchor', 'start')
    .text('log scale');
}
function buildScalesB(stage, ctx) {
  const showName = typeof matchMedia !== 'function' || matchMedia(`(min-width: ${NAME_LABEL_MIN_WIDTH_PX}px)`).matches;
  const gutter = measureEndLabelGutter(stage, [
    { label: BASE.label, value: lastDefinedValue(BASE), fmt: fmtIndex, showName },
    { label: M2.label, value: lastDefinedValue(M2), fmt: fmtIndex, showName }
  ]);
  const x = ctx.d3.scale.scaleTime().domain(ctx.d3.array.extent(BASE.x.values)).range([stage.safe.x, stage.safe.x + stage.safe.width - gutter]);
  const y = ctx.d3.scale.scaleLinear().domain([Math.min(80, LO_B), Math.max(140, HI_B)]).nice().range([stage.safe.y + stage.safe.height, stage.safe.y]);
  return { x, y };
}

function emphasisColor(hex, weight) {
  const w = Math.max(0, Math.min(100, Math.round(weight * 100)));
  return `color-mix(in oklab, ${hex} ${w}%, var(--k-gray) ${100 - w}%)`;
}

// `reveal` drives lineDraw's own stroke-dash reveal fraction; end-label
// opacity tracks `labelOpacity * reveal` so a not-yet-revealed line shows
// no orphaned label (§6.2 item 5: direct labels, no halos). `labelOpacity`
// defaults to `opacity` (unchanged behaviour) but can diverge from it —
// S2-2 item 1: M2's own end label needs to stay choreographed to
// `m2CalloutOpacity` (fade in only at F3) while the M2 LINE itself must
// stay opacity 1 throughout, the same split the deleted hand-rolled
// `m2-callout` text used to encode via two separate elements.
function drawLine(target, series, scales, reveal, emphasis, opacity, fmt, endLabel = true, nameLabel = false, labelOpacity = opacity, strokeWidth = 1) {
  const painted = { ...series, color: { hex: emphasisColor(series.color.hex, emphasis) } };
  const r = lineDraw(target, painted, scales, reveal, { fmt, opacity, endLabel, nameLabel, strokeWidth });
  r.path.classed('mark', true);
  if (r.label) {
    const resolved = labelOpacity * reveal;
    r.label.classed('label', true).attr('opacity', resolved);
    // S2-2-fix-b P1-1: same exemption as 01-three-regimes.js's own
    // `drawLine` — a resolved-opacity-0 label (M2's callout before F3, or
    // the phase-mean trace before it starts revealing) must be
    // `display:none` so declutterLabels/avoidPathCollisions/labelLeaders
    // skip it as the phantom obstacle it would otherwise be.
    r.label.attr('display', resolved > 0 ? null : 'none');
  }
}

// One shared x-axis, morphing between panel A's daily scale and panel B's
// monthly one at fraction `panelT` (§6.1 F2: "axis morph with a state
// fraction") — the primitive this scene exists to exercise.
function drawAxis(stage, xA, xB, panelT) {
  // §3.1 idempotency (same reasoning as 01-three-regimes.js's own
  // `drawAxis`): tickCollide mutates the DOM after render, so a persisted
  // `g.axis` re-`.call()`ed by axisMorph every frame could strand a tick
  // whose `<text>` a prior frame's collide pass already removed. Rebuild
  // from a fresh `<g>` every draw call — only 2 domain-endpoint ticks are
  // ever passed here today (no `ticks:` option, same as before this
  // item), so `tickCollide`'s own `n < 3` guard is a no-op in practice,
  // but the wiring stays correct if a future beat ever adds boundary
  // ticks to this shared axis.
  //
  // S2-2-fix-c: `class="axis x-axis"` (was bare `axis`) + a compound
  // removal selector — panel A now has its OWN `.axis`-classed group
  // (`drawYAxisA`, nested inside `gA`, itself a `stage` descendant), so a
  // bare `stage.select('g.axis')` would match whichever of the two comes
  // first in document order, not necessarily this one. Same fix as
  // `01-three-regimes.js`'s own identical collision.
  stage.select('g.axis.x-axis').remove();
  const axisG = stage.append('g').attr('class', 'axis x-axis').attr('transform', `translate(0,${stage.safe.y + stage.safe.height})`);
  axisMorph(axisG, xA, xB, panelT, { format: monthLabel });
  tickCollide(axisG);
}

// v1 comment, preserved (`story/scenes/02-confidence.js`
// "A8-register-e item 3"): `boxesIntersect` — no primitive exports it,
// same reason 03-treasury.js/01-three-regimes.js each carry their own copy.
// S2-1 (1px, matching `tools/check-text-overlap.mjs`'s own >1px-in-both-
// axes overlap definition — a shared edge is not a collision here either).
const FLAG_MARGIN = 1;

function boxesIntersect(a, b) {
  return (
    a.x < b.x + b.width + FLAG_MARGIN &&
    a.x + a.width + FLAG_MARGIN > b.x &&
    a.y < b.y + b.height + FLAG_MARGIN &&
    a.y + a.height + FLAG_MARGIN > b.y
  );
}

const FLAG_ROW_STEP = 10;

// v1 comment, preserved ("A8-register-f item 11 follow-up"): the window is
// derived from PIXELS via `x.invert`, not a fixed day-count, so it scales
// with whatever x-scale density the current viewport actually has; the
// obstacle's vertical extent is the real min/max rendered y of each
// series across every sample in that window (not one sample).
function localLineObstacles(x, y, date, halfWidthPx = 15) {
  const cx = x(date);
  const dateLo = x.invert(cx - halfWidthPx);
  const dateHi = x.invert(cx + halfWidthPx);
  const boxes = [];
  for (const series of [BLUE_GAP, CCL_GAP]) {
    let lo = Infinity;
    let hi = -Infinity;
    const dates = series.x.values;
    for (let i = 0; i < dates.length; i += 1) {
      if (dates[i] < dateLo || dates[i] > dateHi) continue;
      const v = series.y[i];
      if (v == null || !Number.isFinite(v)) continue;
      const py = y(v);
      if (py < lo) lo = py;
      if (py > hi) hi = py;
    }
    if (!Number.isFinite(lo)) continue;
    boxes.push({ x: cx - halfWidthPx, y: lo - 7, width: halfWidthPx * 2, height: hi - lo + 14 });
  }
  return boxes;
}

// Typographic event flags. S2-1: v1's own adjacent-flag-aware layout
// (`drawVlines`, "A8-register-e item 3" / "A8-register-f item 11"),
// ported — three candidate treatments tried in x order, the first that
// collides with nothing already placed (another flag's own label, or a
// real obstacle box sampled off both data lines at that date) wins:
// (1) bottom-anchored, reading upward; (2) top-anchored, reading downward
// (same -90deg rotation, `text-anchor: end` grows it the OTHER way); (3)
// either anchor with a small x stagger, cascading further right. `.join()`
// (§3.1) sets up the structural line+text nodes; the candidate cascade
// below is inherently per-node sequential (each flag's obstacles include
// every flag already placed this pass) so it runs as a plain loop over
// `[{d, node}]` sorted by date, same order `placed` accumulates in v1.
//
// `extraObstacles` (new, not in v1 — v1 wiped+redrew per beat so its own
// call order never had to think about this): real bboxes of already-drawn
// text this pass should also steer clear of. `draw` here (§3.1) calls this
// once per frame, order matters — the caller draws panel A's own lines +
// declutters their end labels FIRST, then passes those settled bboxes in,
// so a flag never lands on top of one (measured: "BA election" vs "0.7 %"
// at 390px before this wiring, drawFlags ran before any line existed).
// `getBBox()` excludes the element's OWN `transform` attribute (SVG spec:
// local geometry only, pre-transform) — for a plain axis-tick `<text>`
// that transform lives on the PARENT `<g>` (tickCollide.js's own
// "TICK-LOCAL" header comment), but a flag's `-90deg` rotation is set on
// the very node being measured, so `getBBox()` here would report the
// UN-rotated horizontal run (width ≈ text length, height ≈ font size) —
// backwards for a candidate that is actually painted as a narrow vertical
// sliver (measured: a "collides" check that should reject two adjacent
// rotated flags instead passed them straight through). `getBoundingClientRect()`
// includes every transform, own and ancestors'; subtracting the stage
// SVG's own screen position converts it back to the same local space
// `localLineObstacles`/`extraObstacles` already use (both scale-derived,
// no rotation involved) so every obstacle in this pass stays comparable.
function realLocalBox(node, svgRect) {
  const r = node.getBoundingClientRect();
  return { x: r.x - svgRect.x, y: r.y - svgRect.y, width: r.width, height: r.height };
}

function drawFlags(target, x, y, safe, ctx, opacity, extraObstacles = []) {
  const svgRect = target.node().ownerSVGElement.getBoundingClientRect();
  const vlines = vlinesFromSpec(ctx.specs[SPEC_A]);
  const g = target.selectAll('g.vlines').data([null]).join('g').attr('class', 'vlines');
  const flagG = g
    .selectAll('g.flag')
    .data(vlines, (d) => d.text)
    .join((enter) => {
      const gg = enter.append('g').attr('class', 'flag');
      gg.append('line').attr('class', 'mark leader');
      gg.append('text').attr('class', 'mark annot');
      return gg;
    });
  flagG
    .select('line.leader')
    .attr('x1', (d) => x(d.x))
    .attr('x2', (d) => x(d.x))
    .attr('y1', safe.y)
    .attr('y2', safe.y + safe.height)
    .attr('opacity', opacity);

  const flagged = [];
  flagG.each(function each(d) {
    flagged.push({ d, node: this });
  });
  flagged.sort((a, b) => a.d.x - b.d.x);

  const placed = [];
  flagged.forEach(({ d, node }) => {
    const textNode = node.querySelector('text.annot');
    const cx = x(d.x);
    const bottomCandidate = (dx) => {
      const px = cx + 4 + dx;
      const py = safe.y + safe.height - 4;
      return { x: px, y: py, transform: `rotate(-90 ${px} ${py})`, anchor: 'start' };
    };
    const topCandidate = (dx) => {
      const px = cx + 4 + dx;
      const py = safe.y + 12;
      return { x: px, y: py, transform: `rotate(-90 ${px} ${py})`, anchor: 'end' };
    };
    // S2-2-fix-c: two more candidates (dx=3*step) — measured, 390: three
    // real event dates (BA election/US swap/Indexed band) land within 85
    // days of each other on this panel's own ~3.2-year domain, and this
    // panel's own new y-axis gutter (Q11's sibling item, this file's own
    // `measureYAxisGutterA`) narrows the SAME shared plot width the
    // cascade's `dx` steps operate in — the original 6 candidates (0/1/2
    // stagger steps × top/bottom) were all still-colliding for the third
    // flag at 390px, and the loop's own "best-effort: keep the last
    // candidate tried" fallback then used whichever of those 6 was tried
    // LAST, not the least-bad — which happened to be a real ~1.2px overlap
    // against the second flag. One more stagger tier gives the loop a
    // candidate with real room instead.
    const candidates = [
      bottomCandidate(0),
      topCandidate(0),
      bottomCandidate(FLAG_ROW_STEP),
      topCandidate(FLAG_ROW_STEP),
      bottomCandidate(FLAG_ROW_STEP * 2),
      topCandidate(FLAG_ROW_STEP * 2),
      bottomCandidate(FLAG_ROW_STEP * 3),
      topCandidate(FLAG_ROW_STEP * 3)
    ];
    const obstacles = [...placed, ...localLineObstacles(x, y, d.x), ...extraObstacles];
    textNode.textContent = d.text;
    let chosenBox = null;
    for (const cand of candidates) {
      textNode.setAttribute('x', cand.x);
      textNode.setAttribute('y', cand.y);
      textNode.setAttribute('transform', cand.transform);
      textNode.setAttribute('text-anchor', cand.anchor);
      const box = realLocalBox(textNode, svgRect);
      if (!obstacles.some((p) => boxesIntersect(box, p))) {
        chosenBox = box;
        break;
      }
      chosenBox = box; // best-effort: keep the last candidate tried even if it still collides
    }
    placed.push(chosenBox);
    textNode.setAttribute('opacity', opacity);
  });
}

// S2-2-fix-b P1-5: the pipeline's own monthly-mean "Gap %" column,
// `output/tables/table1_phase_summary.md` (`R/01_descriptives.R`'s
// `tab <- m |> group_by(phase, phase_label) |> summarise(gap_mean =
// mean(gap_blue, na.rm = TRUE), ...)`, where `m` is the MONTHLY panel —
// i.e. the mean of each month's own already-monthly `gap_blue` value, not
// a mean of the daily series this scene actually has (`RAW_A`/`BLUE_GAP`).
//
// Deviation: reproduced from `BLUE_GAP`'s own daily values (mean-of-
// monthly-means of the daily series, phase by phase, using
// `config/params.yaml`'s own phase date boundaries) — matches the table to
// one decimal for phases 0/2/3 (100.9/2.1/1.4) but NOT phase 1 (28.9 vs
// the table's 27.6): December 2023's mid-month regime shift (the
// deval/Milei-transition spike collapsing ~185 -> ~17-30 within the same
// calendar month) makes a straight daily mean diverge from whatever
// monthly-frequency series `panel_monthly.csv`'s own `gap_blue` column
// actually is (confirmed NOT reproducible from `panel_daily.csv`'s own
// per-month mean either — `data/panel_monthly.csv`'s December 2023
// `gap_blue` is 50.42, a plain daily mean of that same month from
// `panel_daily.csv` is 72.59; some other monthly-frequency computation or
// source feeds that column, out of this scene's own data and this item's
// fence). A published chart must not show a number the note's own table
// contradicts, so the table's own four numbers are taken directly rather
// than the scene's unreproducible arithmetic.
const PHASE_MEAN_PCT = [100.9, 27.6, 2.1, 1.4];

// S2-crit-fix P1-6 (scene 2's own instance, the critique's "phase-mean
// label" item): `phaseMeanTrace`'s own vertex count — 2 flat-segment
// endpoints per phase, `PHASE_MEAN_PCT.length` phases (see
// `phaseMeanTrace`'s own array-building comment below) — needed by
// `liftPhaseMeanLabel` without re-deriving it from `bandsFromSpec` on
// every draw call.
const PHASE_MEAN_VERTEX_COUNT = PHASE_MEAN_PCT.length * 2;

// S2-crit-fix P1-6: "Phase mean" is deliberately given neither declutter
// nor avoid (fix-b's own Deviation — a combined pass broke the settled
// Blue-gap/CCL-gap pair; a static-obstacle-only pass pushed Phase mean
// 44.7px off its own terminus), so a reader mid-scrub crossing a step
// boundary (100.9 -> 27.6 -> 2.1 -> 1.4 %, a symlog y-scale, puts
// consecutive phases 100s of px apart) meets the label sitting exactly
// inside the two live gap series it is walking through — "landing
// outside the spaghetti," brief. `tools/check-text-overlap.mjs`'s own
// label-terminus rule only samples the SETTLED (t=1) frame and caps the
// label 16px from the trace's OWN true final vertex — a constant lift
// big enough to clear the tangle (well over 16px) breaks that cap
// outright (measured previously: fix-b's own 44.7px attempt did exactly
// this). So the lift TAPERS to exactly 0 by the time the trace reaches
// its own final vertex (`idx === PHASE_MEAN_VERTEX_COUNT - 1`, i.e.
// t=1): the settled position is byte-identical to before this change,
// and every t=1 checker rule (label-terminus, text-text, label-order)
// is unaffected. It is largest while the reader is mid-sweep, on an
// earlier phase, where nothing downstream constrains it.
// label-continuity's own cap (8px, relative motion between consecutive
// scrub frames) is satisfied by construction: the taper changes by at
// most `PHASE_MEAN_LIFT_PX / (PHASE_MEAN_VERTEX_COUNT - 1)` between two
// frames that advance the index by one step (~1.7px at the constants
// below), far under the cap; label-exiled (60px, absolute, per frame) is
// satisfied because the lift never exceeds `PHASE_MEAN_LIFT_PX` itself.
const PHASE_MEAN_LIFT_PX = 12;
function liftPhaseMeanLabel(gA) {
  const label = gA.select('text.line-draw-label[data-label="Phase mean"]');
  const node = label.node();
  if (!node) return;
  const pathNode = gA.select('path.line-draw[data-label="Phase mean"]').node();
  const idx = pathNode ? Number(pathNode.getAttribute('data-label-idx')) : NaN;
  if (!Number.isFinite(idx)) return;
  const denom = PHASE_MEAN_VERTEX_COUNT - 1;
  const taper = denom > 0 ? Math.max(0, Math.min(1, (denom - idx) / denom)) : 0;
  const lift = PHASE_MEAN_LIFT_PX * taper;
  if (lift > 0) {
    const y = Number(node.getAttribute('y'));
    if (Number.isFinite(y)) label.attr('y', y - lift);
  }
}

// One flat segment per SPEC phase (now FOUR, including phase 0 — the
// unshaded baseline region `01-three-regimes.js`'s own `drawBandLabels`
// draws from the x-domain start to `bands[0].from`, same convention here)
// at that phase's own pipeline-authoritative mean — `lineDraw`'s reveal
// fraction sweeps it left to right, its own end label doubling as the live
// readout (no separate scan cursor needed).
function phaseMeanTrace(ctx) {
  const bands = bandsFromSpec(ctx.specs[SPEC_A]);
  const [domainStart] = ctx.d3.array.extent(BLUE_GAP.x.values);
  const xs = [domainStart, bands[0].from];
  const ys = [PHASE_MEAN_PCT[0], PHASE_MEAN_PCT[0]];
  bands.forEach((b, i) => {
    xs.push(b.from, b.to);
    ys.push(PHASE_MEAN_PCT[i + 1], PHASE_MEAN_PCT[i + 1]);
  });
  return { label: 'Phase mean', color: { hex: 'var(--k-crimson)' }, x: { values: xs }, y: ys };
}

// §6.1 frame states — flat numeric, identical keys every beat (§3.1).
const F0_FROM = { gapReveal: 0, phaseTraceReveal: 0, panelT: 0, baseEmphasis: 1, m2CalloutOpacity: 0 };

export default {
  id: '02-confidence',
  title: CAP.title,
  alt: CAP.alt,
  big: CAP.big,
  series: [
    { label: BLUE_GAP.label, x: BLUE_GAP.x, y: BLUE_GAP.y },
    { label: CCL_GAP.label, x: CCL_GAP.x, y: CCL_GAP.y },
    { label: BASE.label, x: BASE.x, y: BASE.y },
    { label: M2.label, x: M2.x, y: M2.y }
  ],
  beats: [
    // F0 (eased, `from` seeds a real draw-in on scene entry — §6.1): the
    // premium exceeded 100 % across 2022-23; panel A lines + 5 event flags.
    {
      motion: 'eased',
      caption: CAP.beats[0],
      from: F0_FROM,
      state: { ...F0_FROM, gapReveal: 1 }
    },
    // F1 (scrub): the phase-mean trace sweeps the four phases.
    {
      motion: 'scrub',
      caption: CAP.beats[1],
      state: { gapReveal: 1, phaseTraceReveal: 1, panelT: 0, baseEmphasis: 1, m2CalloutOpacity: 0 }
    },
    // F2 (eased): crossfade to panel B, axis morphs with the same fraction.
    {
      motion: 'eased',
      caption: CAP.beats[2],
      state: { gapReveal: 1, phaseTraceReveal: 1, panelT: 1, baseEmphasis: 1, m2CalloutOpacity: 0 }
    },
    // F3 (eased): M2 emphasised via its own named callout, base demoted.
    {
      motion: 'eased',
      caption: CAP.beats[3],
      state: { gapReveal: 1, phaseTraceReveal: 1, panelT: 1, baseEmphasis: 0, m2CalloutOpacity: 1 }
    }
  ],
  draw(stage, state, ctx) {
    const safe = stage.safe;
    const A = buildScalesA(stage, ctx);
    const B = buildScalesB(stage, ctx);

    drawAxis(stage, A.x, B.x, state.panelT);

    // S2-2 item 3 fix: the wipe between panels used to be ONLY a group-
    // level `opacity` — visually correct (SVG opacity compositing applies
    // to the whole subtree), but `getComputedStyle()` on a CHILD path
    // still reports that path's own `opacity` attribute (1), not the
    // ancestor's — the exact same read `avoidPathCollisions`/S2-9's own
    // checker both do. Measured: at beat 0 (panelT=0, panel B fully
    // invisible), the checker still flagged panel B's own "Real base"/
    // "Real M2" PATHS striking panel A's visible text, because those paths
    // still computed `opacity: 1`. `panelT` only ever takes 0 or 1 at this
    // scene's own defined beats (never a mid-tween value at a `seek()`-
    // sampled point), so passing it straight down to each line's own
    // `opacity` argument (below) composites to the exact same visual
    // result as before while making the invisible panel's paths correctly
    // read `opacity: 0` and get excluded.
    const panelAOpacity = 1 - state.panelT;
    const panelBOpacity = state.panelT;

    const gA = stage.selectAll('g.panel-a').data([null]).join('g').attr('class', 'panel-a');
    // `lineDraw`'s own end-label edge-flip/axis-clamp reads `sel.safe` — true
    // for `stage` itself, not for a plain sub-`<g>` (v1 `wipeBeat`'s own
    // "carry it over explicitly" comment, same root cause).
    gA.safe = safe;
    gA.attr('opacity', panelAOpacity);
    // S2-2 item 3 fix, continued: `opacity:0` alone still leaves every
    // descendant TEXT node a real (if invisible) candidate for the
    // checker's path-vs-text/text-vs-text rules — S2-1 as-built note 6,
    // opacity:0 text is deliberately NOT exempted. `display:none` IS
    // exempted, and (unlike `opacity`) collapses every descendant's own
    // layout to a zero-size rect / a `getScreenCTM()` that resolves to
    // null — both already-guarded exits in this file's own
    // `collectMarkSamples`-style code and in the checker itself. Safe to
    // gate on an exact 0 here because `panelT` never takes a value other
    // than 0 or 1 at any beat this scene defines (see above) — a live
    // scroll-driven crossfade still animates through intermediate opacity
    // values with `display` unset the whole time.
    gA.attr('display', panelAOpacity > 0 ? null : 'none');
    // S2-2-fix-c: panel A's new y-axis + its "log scale" annotation, both
    // children of `gA` so they inherit its own opacity/display fade —
    // no separate state key needed (unlike `01-three-regimes.js`'s
    // `yAxisOpacity`, which exists because that scene's y-axis fades in
    // mid-scene; this one is on from panel A's own first frame).
    drawYAxisA(gA, A.y, A.x.range()[0]);
    drawLogScaleAnnot(gA, A.x.range()[0], safe);
    // S2-2 item 1 (Nik's ruling): Blue gap / CCL gap carry their own name.
    // The phase-mean trace keeps the default (value-only) — it is not one
    // of the ruling's named series.
    drawLine(gA, BLUE_GAP, A, state.gapReveal, 1, panelAOpacity, fmtPct, true, true);
    drawLine(gA, CCL_GAP, A, state.gapReveal, 1, panelAOpacity, fmtPct, true, true);
    // S2-2-fix-b P1-5: `nameLabel: true` so the end label reads "Phase mean
    // 1.4 %" (not a bare, referent-less number — the same defect class
    // item 1's ruling fixed for the other two lines here). Crimson stays
    // (§1.5 palette — the phase-mean trace is a `k-crimson` derived
    // series, same as CCL gap), but a thinner stroke (0.75 vs the data
    // lines' default 1) keeps it visually subordinate to the two REAL
    // series it's derived from.
    drawLine(gA, phaseMeanTrace(ctx), A, state.phaseTraceReveal, 1, panelAOpacity, fmtPct, true, true, undefined, 0.75);
    // S2-crit-fix P1-6: mid-scrub-only lift, tapering to 0 by t=1 — see
    // the constant's own header comment above. Runs before declutter/
    // avoid (which already skip this label, per `gapLabelSelector`
    // below) and before `gaLabelBoxes` captures every label's bbox for
    // `drawFlags`, so a flag placed after this point sees the lifted
    // position, not the pre-lift one.
    liftPhaseMeanLabel(gA);
    // S2-1: v1's own call site (`gapOverviewBeat`/`gapScrubBeat`, ~313/
    // ~359) — the gap lines' end labels (now three, with the phase-mean
    // trace's own readout) converge the same way theirs did. `draw` runs
    // every frame (§3.1) and `lineDraw` above already reset every label's
    // own x/y from data, so a fresh declutter call each time is idempotent.
    //
    // S2-2-fix-b P1-1: split into a STABLE pass (Blue gap/CCL gap — always
    // fully revealed by the time this beat's own scrub starts) and Phase
    // mean, the one label that APPEARS mid-beat (F1's own
    // `phaseTraceReveal` sweeping 0→1). Running all three through
    // declutter/avoid together let declutterLabels' symmetric-around-
    // centroid spread shift the STABLE pair the instant Phase mean's
    // sweeping position entered their cluster radius — measured: "CCL gap"
    // jumping a clean one-stack-step (28px) with its OWN anchor delta at
    // exactly 0, i.e. not a real move, a re-stack triggered by a new
    // arrival — exactly the failure mode the brief names ("a mid-beat
    // appearance must not re-stack its neighbours"). Declutter/avoid the
    // stable pair on their own selector only.
    //
    // Phase mean itself is deliberately given NEITHER declutter NOR avoid.
    // A first attempt fed it its own `avoidPathCollisions` pass (dodging
    // the settled pair's boxes as `extraObstacles`) — measured, this did
    // NOT fix continuity/exile: Phase mean's own dy jumps (-132, +314, -54
    // px at the same t-steps) were byte-identical with and without that
    // pass, proving the dodge wasn't against the settled pair at all — it
    // was `findClearDy` reacting to Blue gap/CCL gap's own REVEALED PATHS
    // (real marks, not the excluded self-path; `excludeSelfSamples` only
    // excludes a label's OWN series), which Phase mean's label
    // legitimately crosses as it sweeps the full x-domain through a y-range
    // that spans 100.9%→1.4% — a real geometry conflict, not a spurious
    // one, but one the round-3 rule's 8px/0.05t budget cannot absorb
    // either way. Left at its raw computed position it tracks its anchor
    // exactly (zero residual every frame bar the axis-row clamp, which the
    // checker already exempts via `data-y-clamped`); the checker's
    // text-text/path-text rules only sample the settled t=1 frame per
    // beat, not mid-scrub, so a brief visual crossing mid-sweep is the
    // accepted trade. See report `Deviation:` for the terminus-cap
    // consequence (Phase mean's own final position now sits wherever its
    // real anchor is, unshifted).
    // A THIRD attempt (tried, measured, reverted — kept here as the
    // record): dodge only the stable pair's settled rects with
    // mark-sampling switched off (`markSelector` matched against nothing),
    // so the obstacle set never moves within the beat. It DID clear the
    // text-text overlap below (8/8) but pushed Phase mean's label
    // ~44.7px from its own terminus (cap 16) — genuinely no vertical gap
    // exists between Blue gap and CCL gap's settled rects wide enough to
    // seat a third 14px label, so any nearest-clear search that must fully
    // exit both obstacles walks it out of the cluster entirely, trading a
    // small text-text overlap for a much larger terminus violation. Three
    // fix attempts on this one label (combined pass, mark-based dodge,
    // static-obstacle dodge) is where this stops per this pack's own
    // "stop patching, re-derive" rule — see the report's `Deviation:` for
    // the remaining ~7px text-text overlap and the order swap this leaves.
    const gapLabelSelector = '.line-draw-label:not([data-label="Phase mean"])';
    declutterLabels(gA, gapLabelSelector, 2, safe.y + safe.height - 14, safe.y);
    // S2-2 item 3: now against the MARKS themselves, same idempotency
    // reasoning as declutter above.
    // S2-2-fix-c: `A.x.range()[0]` (not raw `safe.x`) — panel A's own plot
    // now starts to the right of the new y-axis gutter; see
    // `01-three-regimes.js`'s own identical fix for the same reasoning.
    avoidPathCollisions(gA, { labelSelector: gapLabelSelector, clampTop: safe.y, clampBottom: safe.y + safe.height - 14, safeLeft: A.x.range()[0] });
    // S2-2 item 2: hairline back to the true anchor for any label item 3
    // or declutter moved. Must run before the boxes below are captured, so
    // `drawFlags`'s own obstacle list reflects the label's FINAL position.
    labelLeaders(gA, '.line-draw-label');
    // Flags placed LAST, after the lines + their (now-settled) end labels
    // exist — see `drawFlags`'s own `extraObstacles` comment.
    const gaLabelBoxes = gA.selectAll('.line-draw-label').nodes().map((n) => n.getBBox());
    drawFlags(gA, A.x, A.y, safe, ctx, state.gapReveal, gaLabelBoxes);

    const gB = stage.selectAll('g.panel-b').data([null]).join('g').attr('class', 'panel-b');
    gB.safe = safe;
    gB.attr('opacity', panelBOpacity);
    gB.attr('display', panelBOpacity > 0 ? null : 'none');
    gB
      .selectAll('line.hundred')
      .data([null])
      .join('line')
      .attr('class', 'mark leader hundred')
      .attr('x1', safe.x)
      .attr('x2', safe.x + safe.width)
      .attr('y1', B.y(100))
      .attr('y2', B.y(100));
    gB
      .selectAll('text.hundred-annot')
      .data([null])
      .join('text')
      .attr('class', 'annot hundred-annot')
      .attr('x', safe.x)
      .attr('y', B.y(100) - 4)
      .text('100 (Dec 2023)');
    // S2-2 item 1 (Nik's ruling): Real base carries its own name.
    drawLine(gB, BASE, B, 1, state.baseEmphasis, panelBOpacity, fmtIndex, true, true);
    // S2-2 item 1: replaces the hand-rolled `text.m2-callout` this file
    // used to draw by hand (`` `M2 ${fmtIndex(...)}` `` at the series' own
    // last point) precisely BECAUSE `nameLabel` did not exist yet — brief:
    // "That is `nameLabel` done manually … delete the hand-rolled callout
    // and let M2 use `endLabel: true, nameLabel: true`". `labelOpacity`
    // keeps the exact choreography the callout had (invisible until F3,
    // v1's own `m2EmphasisBeat` reasoning) while the LINE itself (the
    // `opacity` argument, unchanged at 1) stays drawn every beat panel B is
    // visible, same as before.
    drawLine(gB, M2, B, 1, 1, panelBOpacity, fmtIndex, true, true, state.m2CalloutOpacity);
    // S2-2 items 2/3: panel B never decluttered its own end labels before
    // (only panel A did) — BASE and M2 now both carry named labels, so the
    // same collision class applies here too (brief: "expect the same class
    // of collision … in S2-2's legends").
    declutterLabels(gB, undefined, undefined, safe.y + safe.height - 14, safe.y);
    avoidPathCollisions(gB, { clampTop: safe.y, clampBottom: safe.y + safe.height - 14, safeLeft: safe.x });
    labelLeaders(gB, '.line-draw-label');
  }
};
